using System;
using System.Runtime;

// Allocate a large array (goes to LOH)
byte[] buffer = new byte[100_000];

Console.WriteLine($"LOH size: {GCSettings.LargeObjectHeapCompactionMode}");
Console.WriteLine($"LOH generation: {GC.GetGeneration(buffer)}");

// Force a full collection to see LOH in action
GC.Collect(2, GCCollectionMode.Forced, blocking: true);

// Check free space before and after compaction
long before = GC.GetGCMemoryInfo().HighMemLoadThresholdBytes;
GCSettings.LargeObjectHeapCompactionMode =
    GCLargeObjectHeapCompactionMode.CompactOnce;
GC.Collect(2, GCCollectionMode.Forced, blocking: true);

byte[] managedBuffer = new byte[8192];

// Pin with fixed (short-lived, safe)
fixed (byte* pinned = managedBuffer)
{
    // Pass pinned pointer to unmanaged API
    NativeMethods.WriteBuffer(pinned, managedBuffer.Length);
} // automatically unpinned here

// Pin with GCHandle (long-lived, must free)
GCHandle handle = GCHandle.Alloc(managedBuffer, GCHandleType.Pinned);
try
{
    IntPtr address = handle.AddrOfPinnedObject();
    NativeMethods.ProcessBuffer(address, managedBuffer.Length);
}
finally
{
    handle.Free(); // must free or the object stays pinned
}
